   "spoken": true,
   "t0": 260.92,
   "t1": 266.28,
   "end": 267.18,
   "text": "As a professional ontologist, can you justify the claim that you don't have concepts?",
   "speech": "As a professional ontologist, can you justify the claim that you don't have concepts?",
   "refs": [],
   "estimated": false,
   "mouth": "059948423000996739998998445887643320000000000003499999548974030078968242888777762000353046643067543033346655430022555522744",
   "words": [0,0,3,0.16,5,0.28,18,0.8,30,1.9,34,2.1,38,2.23,46,2.74,50,2.87,56,3.26,61,3.58,65,3.82,71,4.18,76,4.63]
