   "words": [0,0,3,0.42,14,1.99,23,2.58,30,2.77,36,3.1,49,3.83,56,4.32,66,5.17,71,5.76,76,6.15,82,6.53,88,6.85,91,7.06,96,7.48,105,7.9,113,8.35,118,8.5,122,8.63,131,9.25,134,9.38,138,9.5]
